<?php declare(strict_types=1);
$payhubReady = $payhubReady ?? (isset($db) && $db instanceof PDO && class_exists('PayHub') ? PayHub::enabled($db) : false);
$showFeeCols = !empty($treasurer) && !empty($portalReady ?? (isset($db) && $db instanceof PDO && class_exists('ChurchPortal') && ChurchPortal::ready($db)));
if($showFeeCols && $ledgerRows && isset($db) && $db instanceof PDO && class_exists('PayHub') && !array_key_exists('payhub_fee_total',$ledgerRows[0])){
 PayHub::attachLedgerFees($db,$ledgerRows);
}
?>
<div class="table-wrap"><table id="ledger"><caption class="sr-only">Church offering reports, allocations, confirmed amounts and payment status</caption><thead><tr><?php if($treasurer): ?><th><span class="sr-only">Select</span></th><?php endif; ?><th>CHURCH / REFERENCE</th><th>PERIOD</th><th>TOTAL OFFERING · 100%</th><th>CHURCH RETAINS</th><th>AMOUNT TO PAY</th><th>CONFIRMED</th><?php if($showFeeCols): ?><th>GATEWAY FEES</th><th>NET SETTLED</th><?php endif; ?><th>STATUS</th><?php if(canRemit($user)): ?><th>PAY</th><?php endif; ?></tr></thead><tbody><?php foreach($ledgerRows as $row):
$outstanding=Money::cents($row['provincial_levy_due'])-Money::cents($row['amount_paid']);
$canPayNow=$outstanding>0 && in_array($row['status'],['pending','partial'],true);
$feeAmt=(string)($row['payhub_fee_total']??'0.00');
$netAmt=(string)($row['net_settled_total']??$row['amount_paid']);
?><tr data-status="<?= e($row['status']) ?>"><?php if($treasurer): ?><td data-label="Select"><?php if($row['status']==='pending'): ?><input type="checkbox" name="report_ids[]" value="<?= (int)$row['id'] ?>" class="report-delete-check" data-pending-report><?php else: ?><span class="muted small">—</span><?php endif; ?></td><?php endif; ?><td data-label="Church / reference"><div class="parish-cell"><span class="parish-avatar">✧</span><div><strong><?= e($row['node_name']) ?></strong><small><?= e($row['payment_reference']) ?></small></div></div></td><td data-label="Service period"><?= e(date('M',mktime(0,0,0,(int)$row['period_month'],1))) ?> <?= (int)$row['period_year'] ?></td><td data-label="Total offering · 100%"><?= e(Money::display($row['gross_income'])) ?></td><td data-label="Church retains"><?= e(Money::display(Money::decimal(max(0,Money::cents($row['gross_income'])-Money::cents($row['provincial_levy_due']))))) ?></td><td data-label="Amount to pay"><?= e(Money::display($row['provincial_levy_due'])) ?></td><td data-label="Confirmed amount"><?= e(Money::display($row['amount_paid'])) ?></td><?php if($showFeeCols): ?><td data-label="Gateway fees"><?= Money::cents($feeAmt)>0?e(Money::display($feeAmt)):'<span class="muted small">—</span>' ?></td><td data-label="Net settled"><?= Money::cents($row['amount_paid'])>0?e(Money::display($netAmt)):'<span class="muted small">—</span>' ?></td><?php endif; ?><td data-label="Status"><span class="badge <?= e($row['status']) ?>">● <?= e(ucfirst($row['status'])) ?></span></td><?php if(canRemit($user)): ?><td data-label="Pay now"><?php if($canPayNow && $payhubReady): ?><button type="button" class="secondary pay-now-inline" data-pay-now="<?= (int)$row['id'] ?>" data-pay-amount="<?= e(Money::decimal($outstanding)) ?>">Pay now</button><?php elseif($canPayNow): ?><a class="text-link" href="index.php?page=remittances&pay=bank#payment-options">Record payment</a><?php else: ?><span class="muted small">—</span><?php endif; ?></td><?php endif; ?></tr><?php endforeach ?><?php if(!$ledgerRows): ?><tr><td colspan="<?= ($treasurer?8:7)+($showFeeCols?2:0)+(canRemit($user)?1:0) ?>"><div class="empty"><span>⇄</span><h3>No remittances yet</h3><p>Submitted offerings appear here.</p></div></td></tr><?php endif ?></tbody></table></div>
